const sensitive = new Set(["authorization","cookie","password","token","secret","apiKey","accessToken","refreshToken"]);
export const redact = (input: Record<string, unknown>) => Object.fromEntries(Object.entries(input).map(([k,v]) => [k, sensitive.has(k) ? "[REDACTED]" : v]));
export const safeError = (error: unknown): Record<string, unknown> => error instanceof Error ? { name: error.name, message: error.message } : { message: "unknown_error" };

