type Fields = Record<string, unknown>;
const write = (level: string, scope: string, event: string, fields: Fields = {}) => console.log(JSON.stringify({ timestamp: new Date().toISOString(), level, scope, event, ...fields }));
export const createLogger = (scope: string) => ({
  debug: (event: string, fields?: Fields) => write("debug", scope, event, fields),
  info: (event: string, fields?: Fields) => write("info", scope, event, fields),
  warn: (event: string, fields?: Fields) => write("warn", scope, event, fields),
  error: (event: string, fields?: Fields) => write("error", scope, event, fields)
});
